import pathlib,json,html,re,collections
B=pathlib.Path(__file__).resolve().parents[1]
def load(p):return json.loads((B/p).read_text(encoding='utf-8-sig'))
def esc(x):return html.escape(str(x))
def val(x):
 if isinstance(x,(dict,list)):return '<pre>'+esc(json.dumps(x,ensure_ascii=False,indent=2))+'</pre>'
 text=esc(x).replace('\n','<br>')
 rewardicons={'gold':'Gold1','life':'Heart Infinity','noads':'NOads','shufflebooster':'MiniBoosterShuffle','undobooster':'MiniBoosterUndo','capacitybooster':'MiniBoosterCapacity','conveyorcapacitybooster':'MiniBoosterConveyorCapacity','boosters':'MiniBoosters','block':'HorizenentalBlock','battlepasskey':'Key','collectionbartoken':'Ticket','streaktournamenttoken':'WinStreakIcon','selectbooster':'Booster Select'}
 def token(m):
  name=rewardicons.get(m[1].lower());im=next((i for i in imgs if i['name']==name),None)if name else None
  return f'<span class="reward-item"><img src="{im["file"]}" alt="{esc(name)}" title="{esc(name)}">{m[0]}</span>'if im else m[0]
 return re.sub(r'\b([A-Za-z]+):\s*[-\d.]+',token,text)
def table(rows,cols=None):
 if not rows:return '<p>Không có dòng cấu hình.</p>'
 cols=cols or list(rows[0]);return '<div class="tablewrap"><table><thead><tr>'+''.join('<th>'+esc(c)+'</th>'for c in cols)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+val(r.get(c,''))+'</td>'for c in cols)+'</tr>'for r in rows)+'</tbody></table></div>'
def rawtable(rows):return table(rows)
reg=load('Data/table-registry.json');imgs=load('Data/images.json');native=load('Data/native-index.json');defs=load('Data/remote-defaults.json');enums=load('Data/enums.json')
def sheet(n):return load(reg['sheets/local/'+n]['file'])
def source(n):
 p=reg['sheets/local/'+n]['file'];return f'<p class="source">Dữ liệu đầy đủ: <a href="{p}">{n}.json</a> · {len(sheet(n))} dòng</p>'
def st(n,title=None):return '<h3>'+esc(title or n)+'</h3>'+rawtable(sheet(n))+source(n)
def evidence(term):
 a=[x for x in native if term in x['method']][:5]
 return '<p class="source">Đối chiếu logic: '+ ' · '.join(f'<a href="{x["evidence"]}">{esc(x["method"])}</a>'for x in a)+'</p>'
def image(name):
 x=next((x for x in imgs if x['name'].lower()==name.lower()),None)
 return f'<figure><img src="{x["file"]}" alt="{esc(x["name"])}"><figcaption>{esc(x["name"])} · asset gốc</figcaption></figure>'if x else ''
def gallery(names):return '<div class="gallery">'+''.join(image(n)for n in names)+'</div>'
def config(name):
 d=next((x for x in defs if x['name']==name),None)
 if not d:return '<p>Không tìm thấy schema tương ứng.</p>'
 return table([{'Thông số':x['name'],'Kiểu':x['type'],'Mặc định constructor':x['value'] if x['value'] is not None else 'Chưa giải được','Nguồn':x['status']}for x in d['fields']])+f'<p class="source"><a href="{d["source"]}">Constructor native</a> · <a href="{d["schema"]}">Schema</a>. Đây là giá trị trước khi nạp asset/remote, không khẳng định giá trị đang chạy.</p>'
pages=[]
def add(file,title,sub,body):pages.append((file,title,sub,body))
notice='<aside>Phạm vi: phân tích tĩnh APK/bundle và native IL2CPP của bản 4.12.0. Nội dung đóng gói, giá trị mặc định và cấu hình server là ba lớp khác nhau. Chưa có bản ghi Remote Config hoặc phiên chơi trực tiếp để xác nhận cohort, giá cửa hàng và event đang bật.</aside>'
add('index.html','Tổng quan','Loop Sort · Game analysis / 25.11.2026',notice+'''<div class="stats"><article><b>1.299</b>level chính / bộ dữ liệu</article><article><b>30</b>màn Daily riêng</article><article><b>44</b>SKU đối chiếu</article><article><b>291</b>hình UI trích xuất</article></div>
<h2>Game vận hành như thế nào?</h2><p>Loop Sort là puzzle phân loại màu dùng các xe chứa (carrier) bố trí quanh một đường băng tải vòng. Hệ thống chọn xe, tìm slot trống trên băng tải, chuyển nhóm vật thể màu và xử lý khi nhóm đi qua xe nhận. Số slot, vị trí xe, chuỗi màu và chướng ngại tạo nên bài toán sắp xếp. Hình ảnh có lớp khối màu cùng hệ thống Sand/Liquid để biểu diễn dòng vật liệu; số token màu trong bảng level không phải số hạt vật lý được vẽ.</p>
<div class="flow"><span>Chọn xe</span>→<span>Đưa nhóm lên slot</span>→<span>Di chuyển quanh vòng</span>→<span>Nhận / xử lý nhóm màu</span>→<span>Tiến trình & phần thưởng</span></div>
<h2>Cách đọc báo cáo</h2><p>Bắt đầu ở Chi tiết level để xem bố cục và quy tắc loop. Vật thể & cơ chế giải thích dữ liệu màu và feature. Các tab kinh tế, IAP, event, Daily và leaderboard tách phần thưởng, điều kiện và cấu hình. Mỗi bảng có liên kết dữ liệu để kiểm tra đầy đủ mà không phải đọc code.</p>'''+gallery(['Booster Conveyor Capacity','CoinRushicon','WinStreakIcon','StarterVisual'])+table([{'Hạng mục':'Tên / phiên bản','Giá trị':'Loop Sort 4.12.0 · versionCode 541'},{'Hạng mục':'Package','Giá trị':'com.Garawell.LoopSort'},{'Hạng mục':'Engine','Giá trị':'Unity 6000.0.77f1 · ARM64 · IL2CPP'},{'Hạng mục':'Đầu vào','Giá trị':'Run-20261123-162851-39ff5e'},{'Hạng mục':'Nguồn phân tích','Giá trị':'1.265 lớp game/tích hợp; 6.191 hàm native; 51 bảng resource; 111 TextAsset'}])+evidence('BlockTransferSystem$$'))
levelbody='''<h2>Tra cứu theo level người chơi nhìn thấy</h2><p>Chọn bộ dữ liệu và nhập level. Bố cục được dựng 3D bằng WebGL: băng tải vòng, xe tím có thành thùng, bánh xe và các lớp màu. Mesh xe và mẫu băng tải được trích trực tiếp từ game; camera orthographic nghiêng 70° theo prefab Cinemachine gốc. Có thể xoay/zoom, đặt lại camera và xem khung màn hình dọc. Vị trí, góc xoay và khoảng cách Spacing lấy từ dữ liệu spline/carrier. Material được chuyển sang WebGL, chưa chạy shader Unity và logic Cinemachine nguyên bản; HUD là bản dựng lại để phân tích. Icon cơ chế gốc và đối số xem ở các thẻ dữ liệu bên dưới. Các ô màu giữ thứ tự token trong cấu hình, không tự giả định hướng lấy từ trên xuống.</p><div class="controls"><label>Bộ dữ liệu <select id="dataset"><option>local</option><option>v18</option><option>statics</option><option>staticring</option><option>daily</option></select></label><label>Level hiển thị <input id="level" type="number" min="1" step="1" value="1" inputmode="numeric" aria-label="Nhập level muốn xem" placeholder="Nhập level"></label><button id="go-level" type="button">Xem level</button><button id="prev" aria-label="Level trước">←</button><button id="next">→</button></div><div id="levelmeta"></div><div id="layout"></div><details><summary>Nguồn model và camera của bản xem 3D</summary><p>Xe sử dụng mesh, hierarchy transform, submesh/material và blendshape trích từ 9 prefab Carriers v2; khối màu dùng mesh group gốc. Cube hidden sử dụng màu xanh xám và texture dấu hỏi của material Hidden Blocker Block (path ID 149); họa tiết được dựng lại bằng shader WebGL tĩnh, chưa mô phỏng chuyển động/dissolve của shader Unity. Băng tải dùng tiết diện mesh gốc, dựng dọc B-spline với midpoint subdivision và Spacing của từng layout. Camera dùng orthographic, góc nghiêng suy ra từ quaternion prefab Cinemachine (70°), Near/Far clip và FramingSize 0,99; căn toàn cảnh gồm xe và băng tải, có padding trên/dưới 3 đơn vị theo CameraConfig.</p><p>Khung dọc có HUD dựng lại và icon booster gốc. Đây là bản xem trạng thái tĩnh: chưa chạy shader/toon Unity, Cinemachine runtime, chuyển động hoặc tiến trình cơ chế trong game. Màu sáng, bóng và framing có thể còn khác ảnh game; không coi HUD 0/slot là dữ liệu phiên chơi. Có thể kéo xoay, zoom rồi bấm Camera gốc để trở về góc mặc định.</p><p class="source"><a href="Data/original-models.json">Model/material/camera trích xuất</a> · <a href="Data/3d-qa.json">Kiểm tra trình xem 3D</a></p></details><div id="stacks"></div><details><summary>Dữ liệu level gốc & spline</summary><p><button id="download-level-json" type="button">Tải JSON level này</button></p><p class="muted">Tải dữ liệu Level, Carrier và Spline như bên dưới, kèm thông tin bộ dữ liệu, level hiển thị và dòng nguồn khi loop.</p><p id="download-level-status" role="status" aria-live="polite"></p><pre id="rawlevel"></pre></details>
<h2>Index, ID và quy tắc loop</h2><p>SavedLevelIdx là chỉ số bắt đầu từ 0. Nhãn màn chơi = SavedLevelIdx + 1. LevelSheet chọn theo vị trí dòng trong danh sách; ID của dòng chỉ là giá trị dữ liệu. Bộ local có N = 1.299 và LevelConstants.MaxLevelOffset = 800.</p><pre>n = level hiển thị − 1
n &lt; 1299: index nguồn = n; lượt = 1
n ≥ 1299: index nguồn = 800 + ((n − 1299) % 499)
              lượt = floor((n − 1299) / 499) + 2</pre><p>Đoạn loop có 499 dòng, từ index 800 đến 1.298, tương ứng ID 801–1.299 trong bộ local. Khi offset ngoài miền hợp lệ, hàm GetCurrent đưa offset về 0. Bảng Constants cũ còn ghi 500, nhưng MainPlaySession đọc LevelConstants (800), vì vậy không dùng 500 để tính loop hiện tại.</p>'''+table([{'Level hiển thị':1,'Saved index':0,'Index nguồn':0,'ID local':1,'Lượt':1},{'Level hiển thị':310,'Saved index':309,'Index nguồn':309,'ID local':310,'Lượt':1},{'Level hiển thị':1300,'Saved index':1299,'Index nguồn':800,'ID local':801,'Lượt':2},{'Level hiển thị':1798,'Saved index':1797,'Index nguồn':1298,'ID local':1299,'Lượt':2},{'Level hiển thị':1799,'Saved index':1798,'Index nguồn':800,'ID local':801,'Lượt':3}])+evidence('LevelSheet$$GetCurrent')+evidence('MainPlaySession$$get_MaxLevelOffset')+'''<h2>Khi nào load biến thể?</h2><p>Local là đường dữ liệu mặc định Sheets/Local. LevelFunnel có cơ chế đọc cấu hình funnel để chọn bộ biến thể và quay về control khi không tìm thấy cấu hình phù hợp. v18, statics, staticring là nội dung đã đóng gói; sự hiện diện của chúng không chứng minh một người chơi đang được server chọn vào bộ đó. Vì chưa thu Remote Config của tài khoản/thiết bị, trình xem cho phép chọn riêng từng bộ thay vì gộp chúng thành một danh sách.</p>'''+table([{'Bộ':k,'Level':v['levels'],'Carrier layout':v['carriers'],'Spline layout':v['splines'],'Token màu':v['blocks'],'Thiếu tham chiếu':len(v['missingReferences'])}for k,v in load('Data/level-summary.json').items()])+'''<h2>Ý nghĩa các trường</h2>'''+table([{'Trường':'Map / Carriers / Spline','Ý nghĩa':'Tham chiếu bố cục, chuỗi màu xe và hình học đường đi.'},{'Trường':'Theme','Ý nghĩa':'Default, Hard, SuperHard; dùng để phân loại màn và tra thưởng.'},{'Trường':'SlotCount','Ý nghĩa':'Số ô chứa nhóm trên băng tải. Local nằm trong khoảng 4–14.'},{'Trường':'CameraRotation / CameraOffset','Ý nghĩa':'Góc xoay / độ lệch tâm theo layout và level; bản 3D áp dụng khi căn khung toàn cảnh.'},{'Trường':'ColorMix','Ý nghĩa':'Giá trị đầu vào cho biến đổi màu. Không đồng nhất với số màu nhìn thấy.'},{'Trường':'ColorData','Ý nghĩa':'A;R;R:B;B…: chữ A/B là nhãn xe, các phần sau là token màu; nhãn rỗng vẫn được bảo toàn.'},{'Trường':'Features','Ý nghĩa':'Gán cơ chế theo nhãn xe, mã feature và đối số; ví dụ A-H_B.'},{'Trường':'Closed / Spacing / Subdivide / BeltLength','Ý nghĩa':'Thông số spline khép kín, khoảng cách, phân đoạn và chiều dài băng.'}])+evidence('LevelFunnel$$')
