glossary=table([{'Cột':'Reward / Rewards / Payouts / Free / Paid','Cách đọc':'Danh sách loại:số lượng; nhiều dòng là nhiều phần nhận. Free/Paid là hai nhánh quyền nhận. life dùng phút; gold dùng tiền mềm; - không có payout tại dòng.'},{'Cột':'Id','Cách đọc':'Khóa của dòng, có thể là thứ hạng, mốc, tên module hoặc SKU tùy bảng; không mặc định là level người chơi.'},{'Cột':'KeyCount / Token / TokenCount','Cách đọc':'Ngưỡng tiến trình để đạt mốc; phân biệt số token nhận mỗi màn trong bảng constants.'},{'Cột':'WinCount / MilestoneCount','Cách đọc':'Yêu cầu số lần thắng / mốc của hệ tương ứng; không phải giá tiền.'},{'Cột':'Arr / Mission','Cách đọc':'Danh sách nhiệm vụ: login đăng nhập, useboosters dùng booster, reveal làm lộ vật thể, win thắng màn, multiplier dùng/đạt hệ số theo bộ đếm module; số sau dấu : là mục tiêu.'},{'Cột':'RequiredBlockCount','Cách đọc':'Ngưỡng điểm Block nhiệm vụ để lấy phần thưởng tiến trình tuần; không phải số hạt trên băng tải.'},{'Cột':'Price / Gifts','Cách đọc':'Giá cấu hình của bước / quà liên kết; Price 0 là bước miễn phí. Kênh mua của bước trả phí cần đối chiếu provider, không tự gán đơn vị Gold.'},{'Cột':'Welcome / Sync','Cách đọc':'Cờ tham gia luồng chào/khởi tạo và đồng bộ lifecycle; Sync không chứng minh scoreboard dùng toàn người thật.'},{'Cột':'Position / Order / ShowLock','Cách đọc':'Vị trí slot Home, loại/thứ tự slot và có trình bày khóa; không quyết định riêng toàn bộ khả dụng event.'}])
agloss=table([{'Field':'game_level','Ý nghĩa':'Level game gắn vào sự kiện, dùng phân tích theo tiến trình.'},{'Field':'days_since_install','Ý nghĩa':'Số ngày kể từ cài đặt để phân nhóm tuổi người dùng.'},{'Field':'game_coin_balance','Ý nghĩa':'Số dư Gold tại thời điểm ghi sự kiện; không phải tổng đã kiếm.'},{'Field':'run_id / name','Ý nghĩa':'Định danh lượt event và tên hệ; phân biệt nhiều kỳ của cùng LiveOps.'},{'Field':'milestone_level / stage_number / milestone_type','Ý nghĩa':'Mốc, bước và loại tiến trình; không tự đồng nhất với level puzzle.'},{'Field':'reward_track_type / pass_status','Ý nghĩa':'Nhánh thưởng và trạng thái quyền pass.'},{'Field':'current_win_streak / max_win_streak','Ý nghĩa':'Chuỗi hiện tại / lớn nhất trong ngữ cảnh sự kiện.'},{'Field':'current_multiplier / max_multiplier','Ý nghĩa':'Hệ số hiện tại / tối đa đã ghi nhận.'},{'Field':'liveops_currency_balance / liveops_currency_collected','Ý nghĩa':'Số dư token event / lượng đã thu; khác với Gold chung.'},{'Field':'tournament_placement','Ý nghĩa':'Vị trí tournament ghi ở thời điểm đo, không chứng minh kết quả cuối.'},{'Field':'item_name / nb_units / transaction_type','Ý nghĩa':'Loại vật phẩm, số đơn vị và loại giao dịch cho event kinh tế.'},{'Field':'placement / impression_trigger','Ý nghĩa':'Vị trí hiển thị và nguồn kích hoạt cơ hội; không tự coi là quảng cáo hoàn tất.'},{'Field':'ooc_trigger / ool_trigger','Ý nghĩa':'Ngữ cảnh thiếu tiền / thiếu mạng để phân tích điểm cản kinh tế.'}])
