css+='\n.level-mode-summary{display:flex;flex-wrap:wrap;align-items:center;gap:12px;padding:14px 0}.difficulty{font-weight:700;padding:7px 15px;border-radius:8px}.difficulty.normal{background:#dbece5;color:#23694b}.difficulty.hard{background:#fff0ce;color:#926017}.difficulty.superhard{background:#f5dbec;color:#922666}.portrait-mode{position:absolute;top:10%;left:5%;font-size:10px;text-transform:uppercase;letter-spacing:1px;padding:2px 7px;border-radius:5px;border:1px solid #8c76af;background:#292044}.portrait-mode.hard{color:#ffce63;border-color:#cf9c39}.portrait-mode.superhard{color:#f39fd4;border-color:#cc5d9e}.portrait-mode.normal{color:#c7d8d8}#level-color-info small{color:#69798b}#level-color-info td{min-width:105px}#level-color-info .swatch{float:left}'
